#!/usr/bin/env python3
"""Build a private, rerunnable companion to the post-seal v1 author analysis."""
import argparse
import os
from pathlib import Path
import nbformat as nb

from analyze_contextual_emoji_two_track_author_v1 import helpers, ROOT


def main():
    p=argparse.ArgumentParser(description=__doc__)
    for name in ('analysis','package','journal'):
        p.add_argument('--'+name,type=Path,required=True)
    args=p.parse_args()
    folder=helpers.private_directory(args.analysis)
    path=folder/'analysis.ipynb'
    if path.exists():
        raise ValueError('Notebook exists; preserve the previous artifact')
    book=nb.v4.new_notebook(metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'}})
    book.cells=[
        nb.v4.new_markdown_cell('# Two-track author pilot: private analysis / 二系列の著者試用\n\n## tl;dr\n\n24/24 scenes were finalized. The 36 judgments contain 26 binary answers and 10 undecidable answers. Bounded matching was decidable in 12/12, meaning in 9/12, and outcome evidence in 5/12. The model agrees with 16/26 binary judgments, but this is not semantic accuracy: its selected positive-worded responses are identical to an answer-by-question-type constant rule. Across the full inventory, 710/816 polarity pairs are inconsistent; all 48 positive-worded explicit-completion controls prefer No.\n\n24場面を確定済み。人の判定可能性は性質の一致12/12、意味9/12、結果の証拠5/12。人とモデルの一致16/26を理解の成績とは扱わない。モデルの質問反転710/816不整合と明示的完了対照48/48のNoにより、意味測定としての妥当性は未確立。'),
        nb.v4.new_markdown_cell('## Context & Methods\n\nHuman-only reading was sealed before current assignment/model comparison. This notebook is a later replay, not another pre-exposure reading. The original journal and v0 records are never changed.\n\n### Key Assumptions\n\nOne author with known previous exposure; 24 reused scenarios and zero new independent scenarios. Two naturalistic questions share a scene. Undecidable, abstention, and missingness remain distinct. Model likelihoods force a binary answer; agreement uses only the response-selected binary subset. No significance, independent-gold, causal, or v0-to-v1 improvement claim. Model/token decomposition is a secondary post-result diagnostic, not a changed primary estimator.\n\nモデル照合前の読解と現在の再実行を区別する。判断保留をNoへ変換しない。著者一人・既存24課題の開発試用で、独立正解や因果効果は主張しない。'),
        nb.v4.new_code_cell(f'from pathlib import Path\nimport sys\nimport json\n\nroot = Path({str(ROOT)!r})\nfolder = Path({str(folder)!r})\npackage = Path({str(args.package.resolve())!r})\njournal = Path({str(args.journal.resolve())!r})\nsys.path.insert(0, str(root / "scripts"))\nimport analyze_contextual_emoji_two_track_author_v1 as human\nimport compare_contextual_emoji_two_track_author_v1 as comparison\nimport diagnose_contextual_emoji_two_track_readout_v1 as diagnostic\n\ndef read(name):\n    return json.loads((folder / name).read_text())\n\ndef table(rows, keys):\n    print(" | ".join(keys))\n    for row in rows:\n        print(" | ".join(str(row[k]) for k in keys))'),
        nb.v4.new_markdown_cell('## Data\n\nThe participant packet, immutable response journal, prior interpretation seal, saved assignment, and pinned model records are the inputs. Private human data stays on this Mac outside Git and SpiralShare. The chronology below is UTC; JST is UTC+9. Elapsed time is wall-clock time, not measured rating latency.\n\n評価票・確定済み回答・読解の封印・割当・保存済みモデル値を入力にする。人のデータはこのMacのGit・共有領域外に留める。'),
        nb.v4.new_code_cell('sealed = read("phase_one_seal.json")\nassert all(human.sha(folder / name) == digest for name, digest in sealed["files"].items())\nfresh_human, items = human.phase_one(package, journal)\nassert fresh_human == read("phase_one_summary.json")\nassert items == read("phase_one_items.json")\nprint("Read-only journal replay, bound interface, source hashes, and saved human summary: identical.")\nprint(json.dumps({"started": fresh_human["batch_started_at_utc"], "finalized": fresh_human["batch_finalized_at_utc"], "human_reading_sealed": sealed["sealed_at_utc"], "comparison_opened": read("comparison_exposure.json")["opened_at_utc"]}, indent=2))'),
        nb.v4.new_markdown_cell('## Results\n\n### 1. Human judgments / 人の回答\n\nCounts refer to judgments within 24 scenes, not 36 independent participants or scenarios. Quality and recognition metadata are not used to remove any response.'),
        nb.v4.new_code_cell('table([{"probe": probe, **counts} for probe, counts in fresh_human["by_probe"].items()], ["probe", "yes", "no", "undecidable", "abstain", "missing"])\nassert fresh_human["judgment_denominators"] == {"planned": 36, "decidable": 26, "undecidable": 10, "abstain": 0, "missing": 0}\nprint("Optional metadata:", fresh_human["language_clear_counts"], fresh_human["recognition_counts"])\nprint("Known exposure:", fresh_human["known_participant_context"])\nprint("Self-report (retained separately):", fresh_human["setup_self_report"])'),
        nb.v4.new_markdown_cell('### 2. Exact-text comparison / 同一文面での照合\n\nRecalculate all saved model scores and the numerical audit, then match the human scenes and positive questions exactly. Negative-worded questions are sensitivity checks; humans were not shown them. No model is loaded.'),
        nb.v4.new_code_cell('fresh, artifacts = comparison.compare(folder, package, write=False)\nassert fresh == read("comparison_summary.json")\nfor name, value in artifacts.items():\n    assert value == read(name), name\nprint("All post-seal analysis artifacts reproduced exactly.")\ntable(fresh["human_by_probe"], ["probe", "judgments", "comparable_binary", "agreement_positive_question", "agreement_negative_wording_sensitivity_only"])\nselected = artifacts["comparison_items.json"]\nassert len(selected) == 36\nconstant_rule_matches = sum(row["model_positive_truth"] is (row["probe"] == "local_match") for row in selected)\nassert constant_rule_matches == 36\nprint("A rule saying Yes for local match and No for both naturalistic questions reproduces", constant_rule_matches, "of 36 selected model answers. This is a post-result diagnostic, not a preregistered comparator.")'),
        nb.v4.new_markdown_cell('### 3. Polarity and explicit-evidence controls / 質問反転と明示対照\n\nNormalize answers to the truth of the underlying proposition. Consistency requires opposite literal Yes/No answers to the true/false wordings. A polarity pair is a repeated view, not an independent scenario. The original full-sequence estimator remains primary.'),
        nb.v4.new_code_cell('table(fresh["polarity_by_carrier_probe"], ["carrier", "probe", "polarity_pairs", "consistent", "inconsistent", "tie"])\ntable(fresh["model_anchor_by_type_polarity"], ["cue", "polarity", "candidate_pairs", "literal_yes", "literal_no", "authored_reference_agreement_not_accuracy"])\nassert fresh["polarity_overall"] == {"polarity_pairs": 816, "consistent": 106, "inconsistent": 710, "tie": 0}\nanchors = [r for r in artifacts["model_inventory_readout.json"] if r["carrier"] == "anchor" and r["cue"] == "complete_report" and r["polarity"] == "positive"]\nassert len(anchors) == 48 and all(r["literal_answer"] is False for r in anchors)\nprint("Full inventory: 1,632 candidate pairs, 24 reused scenarios; no missing scores or tied primary choices.")'),
        nb.v4.new_markdown_cell('### 4. Continuous context-by-cue contrasts / 連続値の文脈×手がかり差\n\nThe full positive- and negative-worded inventory is retained. Each line has 24 scenario contrasts. A positive score interaction is a descriptive likelihood pattern, not sufficient evidence of contextual meaning, emoji superiority, or validated outcome inference.'),
        nb.v4.new_code_cell('table(fresh["context_cue_contrast_by_carrier_probe_polarity"], ["carrier", "probe", "polarity", "n", "mean", "positive", "negative"])\nprint(fresh["contrast_formula"])'),
        nb.v4.new_markdown_cell('### 5. Secondary answer-token decomposition / 事後の採点内訳診断\n\nThe common answer prefix cancels exactly. The primary contrast equals the yes/no token contrast plus the following period-token contrast. Removing that suffix is inspected only as a diagnostic; no primary values or thresholds are replaced.'),
        nb.v4.new_code_cell('token_summary, token_rows = diagnostic.saved_run()\nassert token_summary == read("secondary_token_diagnostic.json")\nprint(json.dumps(token_summary["decomposition"], indent=2))\nprint("Answer-token polarity diagnostic:", token_summary["answer_token_polarity"])\nassert token_summary["primary_estimator_changed"] is False\nassert token_summary["decomposition"]["sign_reversals_excluding_ties"] == 103\nassert token_summary["decomposition"]["answer_token_ties"] == 191\ncomplete_positive = [r for r in token_rows if r["carrier"] == "anchor" and r["cue"] == "complete_report" and r["polarity"] == "positive"]\nassert len(complete_positive) == 48 and all(r["token_truth"] is False for r in complete_positive)\nprint("The 48 positive-worded explicit-completion failures persist without the period suffix.")'),
        nb.v4.new_markdown_cell('## Takeaways\n\nShare with caveats as a private instrument-development analysis. Numerical acquisition and joins are verified; semantic validity of this question/completion format is not established. The human workbench separates some judgments but still conflates event uncertainty with evidence sufficiency. Next, run a small, separately specified question-comprehension and model-readout qualification exercise, with explicit complete/unknown and polarity controls, before any larger emoji experiment. Keep source records, uncertainty, and prior exposure intact. See [the Japanese research note](RESEARCH_NOTE.ja.md) and [English version](RESEARCH_NOTE.md).\n\n私的な測定設計の改善材料として、留意点つきで利用できる。次は大規模化に先立ち、問いの読解と採点形式の小さな動作確認を別々に設計する。モデル内部の意味・因果や絵文字優位は、この結果から主張しない。')
    ]
    nb.validate(book)
    with open(os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600),'w') as f:
        nb.write(book,f)
    print(path)


if __name__=='__main__':main()
